PreInvocation.command:
python3 -c 'import json, os, subprocess, pathlib; required={"filipkrawiec-sdlc", "filipkrawiec-core", "filipkrawiec-workflow", "filipkrawiec-authoring"}; installed=set(); missing=[];
try:
  installed={plugin.get("name") for plugin in json.loads(subprocess.check_output(["agy", "plugin", "list"], text=True, stderr=subprocess.DEVNULL)).get("imports", [])}
except Exception:
  pass
plugin_dir=pathlib.Path(os.environ.get("AGY_IDE_PLUGIN_DIR", os.path.expanduser("~/.gemini/config/plugins")))
for req in list(required):
  if req not in installed and (plugin_dir / req).exists():
    installed.add(req)
missing=sorted(required-installed)
print(json.dumps({"injectSteps":[{"ephemeralMessage":"SDLC notice: missing companion plugins: " + ", ".join(missing)}]} if missing else {}))'
